import zipfile
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/officeDocument/2006/math",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
    "s": "http://schemas.openxmlformats.org/officeDocument/2006/sharedTypes",
    "x": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
}

def col_letter_to_idx(ref):
    letters = "".join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - 64)
    return idx - 1  # 0-based

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    print("Archive members:", names)
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = wb.find("x:sheets", NS)
    sheet_names = [s.get("name") for s in sheets]
    print("Sheet names:", sheet_names)
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rid_to_target = {}
    for rel in rels:
        rid_to_target[rel.get("Id")] = rel.get("Target")
    shared_strings = []
    if "xl/sharedStrings.xml" in names:
        ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss.findall("x:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared_strings.append(text)

    for sheet_el in sheets:
        name = sheet_el.get("name")
        rid = sheet_el.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rid_to_target.get(rid, "")
        if not target.startswith("xl/"):
            target = "xl/" + target.lstrip("/")
        print(f"\n=== Sheet: {name} ({target}) ===")
        ws = ET.fromstring(z.read(target))
        data = ws.find("x:sheetData", NS)
        rows = []
        for row in data.findall("x:row", NS):
            for c in row.findall("x:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("x:v", NS)
                val = None
                if v is not None:
                    raw = v.text
                    if t == "s":
                        val = shared_strings[int(raw)]
                    elif t == "b":
                        val = raw == "1"
                    else:
                        try:
                            val = float(raw)
                            if val.is_integer():
                                val = int(val)
                        except (TypeError, ValueError):
                            val = raw
                f = c.find("x:f", NS)
                if f is not None:
                    val = f"FORMULA({val})" if val is not None else "FORMULA"
                if val is not None:
                    print(f"  {ref}: {val!r}")

